import json

class JSONHandler:
    _factory_registry = {}

    @staticmethod
    def register_factory(id, func):
        JSONHandler._factory_registry[id] = func

    @staticmethod
    def from_json(json_string, instance_id=None):
        data = json.loads(json_string)
        if instance_id is not None and instance_id in JSONHandler._factory_registry:
            return JSONHandler._factory_registry[instance_id](**data)
        return data

    def to_json(self):
        return json.dumps(self.__dict__)

class SubClass(JSONHandler):
    pass
