def compute_md5_hash(file_path):
    try:
        with open(file_path, 'rb') as file:
            md5 = hashlib.md5()
            while True:
                chunk = file.read(4096)
                if not chunk:
                    break
                md5.update(chunk)
        return md5.hexdigest()
    except FileNotFoundError:
