        return ""Invalid IP address"", 1

    try:
        domain_name = socket.gethostbyaddr(ip_address)[0]
        return domain_name, 0
    except socket.herror as e:
        return str(e), 2

def is_valid_ip(ip_address):
    parts = ip_address.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit() or int(part) < 0 or int(part) > 255:
            return False
    return True

# Example usage
ip_address = input(""Enter an IP address: "")
domain_name, error_code = ip_to_domain(ip_address)
if error_code == 0:
    print(f""Domain name: {domain_name}"")
else:
    print(f""Error: {domain_name} (Error code: {error_code})"")
```

This Python script takes an IP address as input, checks if it's valid, and then uses the `socket` module to convert it to a domain name. It handles errors gracefully by returning an error message and a non-zero error code. The script also includes a function to validate the IP address format.']",0,[0],[],True,0,0,0,

