import time

def generate_valid_parentheses(n):
    dp = [[] for _ in range(n + 1)]
    dp[0].append('')

    for i in range(1, n + 1):
        for j in range(i):
            for left in dp[j]:
                for right in dp[i - j - 1]:
                    dp[i].append('({}){}'.format(left, right))

    return dp[n], time.time()

# Example usage
n = 3
combinations, computation_time = generate_valid_parentheses(n)
print(""Valid Parentheses Combinations:"", combinations)
