0,"Write a Python function to implement a priority queue that supports adding, removing, and retrieving the highest priority element. The priority queue should be able to handle different types of elements based on their priority levels, which are represented by integers. Ensure the function is thread-safe and includes methods for checking the current size of the queue and whether it's empty. Additionally, include unit tests to validate the functionality across various scenarios, including edge cases. Use standard Python library functions only for implementing this task.",338,,"['```python
import threading

class PriorityQueue:
    def __init__(self):
        self.queue = []
        self.lock = threading.Lock()

    def add(self, item, priority):
        with self.lock:
            bisect.insort(self.queue, (-priority, item))

    def remove(self):
        with self.lock:
            if not self.queue:
                raise IndexError(""pop from an empty priority queue"")
            return heappop(self.queue)[1]

    def highest_priority(self):
        with self.lock:
            if not self.queue:
                raise IndexError(""highest_priority from an empty priority queue"")
            return self.queue[0][1]

    def size(self):
        with self.lock:
            return len(self.queue)

    def is_empty(self):
        with self.lock:
            return len(self.queue) == 0

import unittest
import bisect
import heapq

class TestPriorityQueue(unittest.TestCase):

    def setUp(self):
        self.pq = PriorityQueue()

    def test_add_remove(self):
        self.pq.add('a', 1)
        self.pq.add('b', 2)
        self.assertEqual(self.pq.remove(), 'b')
        self.assertEqual(self.pq.remove(), 'a')

    def test_highest_priority(self):
        self.pq.add('a', 3)
        self.pq.add('b', 1)
        self.assertEqual(self.pq.highest_priority(), 'a')

    def test_size_empty(self):
        self.assertTrue(self.pq.is_empty())
        self.pq.add('a', 2)
        self.assertFalse(self.pq.is_empty())
        self.pq.remove()
        self.assertTrue(self.pq.is_empty())

if __name__ == ""__main__"":
    unittest.main()
```

