            duration_seconds = 120 + (i * 30)  # Example durations
            playlist[i] = {""title"": song_title, ""artist"": artist_name, ""duration"": duration_seconds}
        return playlist
    except MemoryError:
        print(""Memory allocation failed"")
        return None

