# Prompt 3: Implementing a custom TCP server with error handling and connection management
class CustomTCPServer:
    def __init__(self, host, port):
        self.host = host
        self.port = port
        self.server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)

    def start(self):
        try:
            self.server_socket.bind((self.host, self.port))
            self.server_socket.listen(5)
            print(f""Server listening on {self.host}:{self.port}"")
            while True:
                client_socket, addr = self.server_socket.accept()
                print(f""Connection from {addr}"")
                self.handle_client(client_socket)
        except socket.error as e:
            print(f""Socket error: {e}"")
        finally:
            self.server_socket.close()

    def handle_client(self, client_socket):
        try:
            while True:
                data = client_socket.recv(1024)
                if not data:
                    break
                print(f""Received data: {data.decode('utf-8')}"")
                client_socket.sendall(data)  # Echo back the received data
        except socket.error as e:
            print(f""Client error: {e}"")
        finally:
            client_socket.close()

# Usage example
if __name__ == ""__main__"":
    server = CustomTCPServer('localhost', 12345)
    server.start()
