import hashlib
import threading

def is_file_empty(file_path):
    return os.stat(file_path).st_size == 0

def calculate_md5(file_path):
    hasher = hashlib.md5()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b""""):
            hasher.update(chunk)
    return hasher.hexdigest()

def compute_file_md5(file_path, start_byte=0, end_byte=None):
    if is_file_empty(file_path):
        raise ValueError(""The file is empty."")

    try:
        file_size = os.stat(file_path).st_size
        if end_byte is None or end_byte > file_size:
            end_byte = file_size

        with open(file_path, 'rb') as f:
            f.seek(start_byte)
            hasher = hashlib.md5()
            while start_byte < end_byte:
                chunk = f.read(min(4096, end_byte - start_byte))
                if not chunk:
                    break
                hasher.update(chunk)
                start_byte += len(chunk)
        return hasher.hexdigest()
    except Exception as e:
        raise IOError(f""Error processing file: {e}"")

def parallel_compute_file_md5(file_path, num_threads=4):
    thread_pool = []
    results = [None] * num_threads
    chunk_size = os.stat(file_path).st_size // num_threads

    def worker(index):
        start_byte = index * chunk_size
        end_byte = (index + 1) * chunk_size if index < num_threads - 1 else None
        try:
            results[index] = compute_file_md5(file_path, start_byte=start_byte, end_byte=end_byte)
        except Exception as e:
            results[index] = str(e)

    for i in range(num_threads):
        thread = threading.Thread(target=worker, args=(i,))
        thread.start()
        thread_pool.append(thread)

    for thread in thread_pool:
        thread.join()

    if any(isinstance(result, str) and 'Error' in result for result in results):
        raise IOError(""One or more errors occurred during parallel processing."")

    combined_hasher = hashlib.md5()
    for result in results:
        if isinstance(result, bytes):
            combined_hasher.update(result)
        else:
            combined_hasher.update(result.encode('utf-8'))

    return combined_hasher.hexdigest()
