import Foundation

struct TreeNode {
    var value: (String, Int)
    var left: TreeNode?
    var right: TreeNode?

    init(value: (String, Int)) {
        self.value = value
        left = nil
        right = nil
    }
}

class BinarySearchTree {
    private var root: TreeNode?

    func insert(_ value: (String, Int)) {
        if let node = root {
            insertNode(node: node, value: value)
        } else {
            root = TreeNode(value: value)
        }
    }

    private func insertNode(node: TreeNode, value: (String, Int)) {
        if value.1 < node.value.1 {
            if let left = node.left {
                insertNode(node: left, value: value)
            } else {
                node.left = TreeNode(value: value)
            }
        } else {
            if let right = node.right {
                insertNode(node: right, value: value)
            } else {
                node.right = TreeNode(value: value)
            }
        }
    }

    func search(byHash hashValue: Int) -> String? {
        return searchNode(node: root, hashValue: hashValue)?.value.0
    }

    private func searchNode(node: TreeNode?, hashValue: Int) -> TreeNode? {
        guard let node = node else { return nil }
        if node.value.1 == hashValue {
            return node
        } else if hashValue < node.value.1 {
            return searchNode(node: node.left, hashValue: hashValue)
        } else {
            return searchNode(node: node.right, hashValue: hashValue)
        }
    }

    func retrieve(byHash hashValue: Int) -> String? {
        guard let node = searchNode(node: root, hashValue: hashValue) else { return nil }
        return node.value.0
    }
}

class HashTable {
    private var buckets: [BinarySearchTree]
    private let size: Int

    init(size: Int) {
        self.size = size
        buckets = Array(repeating: BinarySearchTree(), count: size)
    }

    func insert(_ value: String, hashFunction: @escaping (String) -> Int) {
        let hashValue = hashFunction(value) % size
        buckets[hashValue].insert((value, hashValue))
    }

    func search(byHash hashValue: Int) -> String? {
        return buckets[hashValue].search(byHash: hashValue)
    }
}

// Example usage:
let hashTable = HashTable(size: 10)
hashTable.insert(""apple"", hashFunction: { $0.hashValue })
hashTable.insert(""banana"", hashFunction: { $0.hashValue })

if let result = hashTable.search(byHash: ""apple"".hashValue % 10) {
    print(result) // Output: apple
}
