def calculate_factorial(number, verbose=False):
    if not isinstance(number, int) or number < 0 or number > 12:
        raise ValueError(""Input must be a non-negative integer between 0 and 12."")

    factorial = 1
    for i in range(1, number + 1):
        factorial *= i
        if verbose:
            print(f""Step {i}: {factorial}"")

    return factorial

# Example usage:
try:
    result = calculate_factorial(5, verbose=True)
    print(f""The factorial of the number is: {result}"")
except ValueError as e:
    print(e)
