def find_nodes_with_pattern(tree, pattern, callback):
    matching_nodes = []

    def recursive_search(node):
        if not node:
            return

        if callback(node) and pattern in str(node):
            matching_nodes.append(node)

        for child in node.children:
            recursive_search(child)

    recursive_search(tree.root)
    return matching_nodes
