import xml.etree.ElementTree as ET
import json
from Crypto.PublicKey import RSA
from Crypto.Cipher import PKCS1_OAEP
import threading

class XMLJSONRSA:
    def __init__(self, max_size=100):
        self.max_size = max_size
        self.instances = []

    def create_instance(self, num_instances):
        for _ in range(num_instances):
            instance = {'data': [], 'key': RSA.generate(2048), 'lock': threading.Lock()}
            self.instances.append(instance)

    def add_data(self, index, data):
        if 0 <= index < len(self.instances):
            with self.instances[index]['lock']:
                if len(self.instances[index]['data']) < self.max_size:
                    self.instances[index]['data'].append(data)
                else:
                    raise ValueError(""Instance array is at maximum capacity"")

    def transform_to_json(self, index):
        if 0 <= index < len(self.instances):
            with self.instances[index]['lock']:
                return json.dumps({'data': self.instances[index]['data'], 'timestamp': self.get_current_timestamp()})

    def encrypt_data(self, index):
        if 0 <= index < len(self.instances):
            with self.instances[index]['lock']:
                encrypted = []
                for item in self.instances[index]['data']:
                    cipher_rsa = PKCS1_OAEP.new(self.instances[index]['key'])
                    encrypted.append(cipher_rsa.encrypt(item.encode()))
                return encrypted

    def get_current_timestamp(self):
        import time
        return str(time.time())

