import os
import shutil
import argparse

def backup_files(source_path, destination_path):
    if not os.path.exists(source_path):
        print(f""Error: {source_path} does not exist."")
        return

    if not os.path.exists(destination_path):
        print(f""Error: {destination_path} does not exist."")
        return

    archive_file = os.path.join(source_path, ""archive.txt"")

    if os.path.exists(archive_file):
        print(""Warning: archive.txt exists in the source directory. It will be excluded from the backup."")

    try:
        shutil.copytree(source_path, destination_path, ignore=[archive_file], dirs_exist_ok=True)
        print(""Backup completed successfully."")
    except Exception as e:
        print(f""Error during backup process: {e}"")

def parse_arguments():
    parser = argparse.ArgumentParser(description=""Automate file backup process with command-line arguments"")
    parser.add_argument(""source"", type=str, help=""Path to the directory containing files to be backed up"")
    parser.add_argument(""destination"", type=str, help=""Path for the backup location"")

    args = parser.parse_args()

    return args.source, args.destination

if __name__ == ""__main__"":
    source_path, destination_path = parse_arguments()

    if os.path.isfile(destination_path) and not os.access(destination_path, os.W_OK):
        print(f""Error: Destination path is a file and you do not have write permissions."")

    elif os.path.isdir(destination_path) and not os.access(destination_path, os.W_OK | os.X_OK):
        print(f""Error: Destination path is a directory but you do not have write or execute permissions."")

    else:
        backup_files(source_path, destination_path)
