import random
import string

def generate_random_string(length):
    return ''.join(random.choice(string.ascii_letters + string.digits) for _ in range(length))

def generate_payload(min_len, max_len):
    return generate_random_string(random.randint(min_len, max_len))

def validate_user_data_packet(packet):
    if len(packet['destination_address']) < DESTINATION_ADDRESS_LENGTH or len(packet['destination_rnti']) < DESTINATION_RNTI_LENGTH:
        raise ValueError(""Invalid address or RNTI length"")

    if packet['payload'] is not None and (len(packet['payload']) < PAYLOAD_MIN_LENGTH or len(packet['payload']) > PAYLOAD_MAX_LENGTH):
        raise ValueError(""Invalid payload length"")

def generate_user_data_packet():
    packets = []

    for _ in range(5):  # Generate 5 USER_DATA_PACKET_T structures
        destination_address = generate_random_string(DESTINATION_ADDRESS_LENGTH)
        destination_rnti = generate_random_string(DESTINATION_RNTI_LENGTH)
        payload_length = random.randint(PAYLOAD_MIN_LENGTH, PAYLOAD_MAX_LENGTH)
        packet_payload = generate_payload(payload_length) if payload_length > 0 else None

        user_data_packet_t_structure = {
            ""destination_address"": destination_address,
            ""destination_rnti"": destination_rnti,
            ""payload"": packet_payload,
        }

        packets.append(user_data_packet_t_structure)

    return packets

user_data_packets_with_validation = check_valid_packets(generate_user_data_packet())

def check_valid_packets(packets):
    valid_packets = []

    for packet in packets:
        try:
            validate_user_data_packet(packet)
            valid_packets.append(packet)
        except ValueError as e:
            print(f""Packet validation failed: {e}"")

    return valid_packets
