import xml.etree.ElementTree as ET

class XMLHandler:
    _registry = {}

    @staticmethod
    def register(id, factory_function):
        XMLHandler._registry[id] = factory_function

    @classmethod
    def from_xml_string(cls, xml_string):
        root = ET.fromstring(xml_string)
        id = root.get('id')
        if id in cls._registry:
            return cls._registry[id](root)
        else:
            raise ValueError(f""No factory registered for ID: {id}"")

    def to_xml_string(self):
        raise NotImplementedError(""Subclasses must implement this method"")

class UserXMLHandler(XMLHandler):
    @classmethod
    def from_xml_string(cls, xml_string):
        return super().from_xml_string(xml_string)

    def to_xml_string(self):
        root = ET.Element('User')
        root.set('id', str(id(self)))
        # Add other XML elements here
        return ET.tostring(root, encoding='unicode')

