```python
import hashlib
import os

def generate_random_data(size):
    return os.urandom(size)

def calculate_hash(file_path, data=None):
    hasher = hashlib.sha256()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b""""):
            if data is not None:
                hasher.update(data)
            else:
                hasher.update(chunk)
    return hasher.hexdigest()

def validate_file_with_python(filename, expected_hash):
    random_data = generate_random_data(1024)  # Example size
    current_hash = calculate_hash(filename, random_data)
    return current_hash == expected_hash
```

