import socket
from urllib.parse import urlparse

def resolve_hostname(hostname, retries=3, timeout=5):
    for _ in range(retries):
        try:
            return socket.gethostbyname(hostname)
        except socket.gaierror:
            pass
    raise Exception(f""Failed to resolve hostname {hostname} after {retries} attempts"")

class NFAPI_CRC_INDICATION_PDU_T:
    def __init__(self, message_type, status, length, index):
        self.message_type = message_type
        self.status = status
        self.length = length
        self.index = index

def custom_crc_calculation(data):
    crc = 0xFFFF
    for byte in data:
        crc ^= (byte << 8)
        for _ in range(8):
            if crc & 0x8000:
                crc = (crc << 1) ^ 0x1021
            else:
                crc <<= 1
        crc &= 0xFFFF
    return crc

def generate_NFAPI_CRC_INDICATION_PDUs(N, message_types, statuses):
    PDUs = []
    for i in range(N):
        message_type = message_types[i % len(message_types)]
        status = statuses[i % len(statuses)]
        length = random.randint(100, 1000)
        index = random.randint(0, N - 1)
        pdu = NFAPI_CRC_INDICATION_PDU_T(
            message_type=message_type,
            status=status,
            length=length,
            index=index
        )
        data = f""{message_type}{status}{length}{index}"".encode()
        pdu.crc = custom_crc_calculation(data)
        PDUs.append(pdu)
    return PDUs

# Example usage
N = 10
