0,"Design and implement a program that simulates a simple database for managing employee records. The program should allow users to add, retrieve, update, and delete employee information. Each employee record should include fields such as ID, name, position, department, salary, and hire date. The program should enforce data validation to ensure that the ID is unique and within a specified range, the name is not empty or too long, the position and department are valid choices from predefined lists, the salary is within an acceptable range, and the hire date is in a valid format (YYYY-MM-DD). Additionally, include functionality to sort employees by their names or departments.",680,,"['```python
import re
from datetime import datetime

class Employee:
    def __init__(self, id, name, position, department, salary, hire_date):
        self.id = id
        self.name = name
        self.position = position
        self.department = department
        self.salary = salary
        self.hire_date = hire_date

    def __str__(self):
        return f""ID: {self.id}, Name: {self.name}, Position: {self.position}, Department: {self.department}, Salary: {self.salary}, Hire Date: {self.hire_date}""

class EmployeeDB:
    def __init__(self):
        self.employees = []
        self.next_id = 1
        self.valid_positions = [""Manager"", ""Developer"", ""Tester""]
        self.valid_departments = [""Engineering"", ""HR"", ""Marketing""]

    def add_employee(self, name, position, department, salary, hire_date):
        if not (self.next_id <= 100 and self.next_id > 0): raise ValueError(""ID out of range"")
        if not re.match(r'^\S+$', name) or len(name) > 50: raise ValueError(""Invalid name"")
        if position not in self.valid_positions: raise ValueError(""Invalid position"")
        if department not in self.valid_departments: raise ValueError(""Invalid department"")
        if salary < 3000 or salary > 15000: raise ValueError(""Salary out of range"")
        if not re.match(r'^\d{4}-\d{2}-\d{2}$', hire_date): raise ValueError(""Invalid date format"")

        employee = Employee(self.next_id, name, position, department, salary, hire_date)
        self.employees.append(employee)
        self.next_id += 1

    def get_employee_by_id(self, id):
        return next((emp for emp in self.employees if emp.id == id), None)

    def update_employee(self, id, **kwargs):
        employee = self.get_employee_by_id(id)
        if employee:
            for key, value in kwargs.items():
                setattr(employee, key, value)
                if key == ""name"" and not re.match(r'^\S+$', value) or len(value) > 50: raise ValueError(""Invalid name"")
                if key == ""position"" and value not in self.valid_positions: raise ValueError(""Invalid position"")
                if key == ""department"" and value not in self.valid_departments: raise ValueError(""Invalid department"")
                if key == ""salary"" and (value < 3000 or value > 15000): raise ValueError(""Salary out of range"")
                if key == ""hire_date"" and not re.match(r'^\d{4}-\d{2}-\d{2}$', value): raise ValueError(""Invalid date format"")

    def delete_employee(self, id):
        self.employees = [emp for emp in self.employees if emp.id != id]

    def sort_employees_by_name(self):
        return sorted(self.employees, key=lambda x: x.name)

    def sort_employees_by_department(self):
        return sorted(self.employees, key=lambda x: x.department)
