0,"Design a simple employee database program allowing users to add, retrieve, update, and delete records. Each record should include ID, name, position, department, salary, and hire date. Implement data validation for ID uniqueness and range, non-empty name with length restriction, valid position and department choices from predefined lists, salary within an acceptable range, and valid hire date format (YYYY-MM-DD). Include sorting functionality for employees by name or department.",680,,"['```python
import datetime

class Employee:
    def __init__(self, id, name, position, department, salary, hire_date):
        self.id = id
        self.name = name
        self.position = position
        self.department = department
        self.salary = salary
        self.hire_date = hire_date

    @classmethod
    def from_dict(cls, data):
        return cls(**data)

class EmployeeDatabase:
    def __init__(self):
        self.employees = []
        self.id_counter = 1000  # Start IDs from 1000 for uniqueness

    def add_employee(self, name, position, department, salary, hire_date):
        if not isinstance(name, str) or len(name.strip()) == 0:
            raise ValueError(""Name must be a non-empty string."")
        if not isinstance(salary, (int, float)) or salary <= 0:
            raise ValueError(""Salary must be a positive number."")
        try:
            hire_date = datetime.datetime.strptime(hire_date, ""%Y-%m-%d"")
        except ValueError:
            raise ValueError(""Hire date must be in YYYY-MM-DD format."")

        employee_data = {
            ""id"": self.id_counter,
            ""name"": name,
            ""position"": position,
            ""department"": department,
            ""salary"": salary,
            ""hire_date"": hire_date.strftime(""%Y-%m-%d"")
        }
        new_employee = Employee.from_dict(employee_data)
        for emp in self.employees:
            if emp.id == new_employee.id:
                raise ValueError(""Employee ID must be unique."")
        self.employees.append(new_employee)
        self.id_counter += 1

    def get_employee(self, employee_id):
        for emp in self.employees:
            if emp.id == employee_id:
                return emp
        raise ValueError(""Employee not found."")

    def update_employee(self, employee_id, name=None, position=None, department=None, salary=None, hire_date=None):
        employee = self.get_employee(employee_id)
        if name is not None:
            employee.name = name
        if position is not None:
            employee.position = position
        if department is not None:
            employee.department = department
        if salary is not None:
            employee.salary = salary
        if hire_date is not None:
            try:
                employee.hire_date = datetime.datetime.strptime(hire_date, ""%Y-%m-%d"")
            except ValueError:
                raise ValueError(""Hire date must be in YYYY-MM-DD format."")
        employee_data = {
            ""id"": employee.id,
            ""name"": employee.name,
            ""position"": employee.position,
            ""department"": employee.department,
            ""salary"": employee.salary,
            ""hire_date"": employee.hire_date.strftime(""%Y-%m-%d"")
        }
        updated_employee = Employee.from_dict(employee_data)
        for i, emp in enumerate(self.employees):
            if emp.id == updated_employee.id:
                self.employees[i] = updated_employee
                break

    def delete_employee(self, employee_id):
        employee = self.get_employee(employee_id)
        self.employees.remove(employee)

    def sort_employees_by_name(self):
        return sorted(self.employees, key=lambda x: x.name)

    def sort_employees_by_department(self):
        return sorted(self.employees, key=lambda x: x.department)

# Example usage
db = EmployeeDatabase()
db.add_employee(""John Doe"", ""Software Engineer"", ""Engineering"", 80000, ""2019-06-15"")
db.add_employee(""Jane Smith"", ""Project Manager"", ""Management"", 95000, ""2017-03-20"")
sorted_by_name = db.sort_employees_by_name()
for emp in sorted_by_name:
    print(f""ID: {emp.id}, Name: {emp.name}, Position: {emp.position}"")
