column3:
 err != nil {
		log.Printf(""Validation failed for Checksum: %v"", err)
		return nil, nil, err
	}

	return p, c, nil
}

func validatePacket(p *Packet) error {
	if p.PacketSequenceNumber < 0 || p.PacketSequenceNumber > 999 {
		return errors.New(""PacketSequenceNumber out of valid range"")
	}
	if p.TransmissionPower < 0 || p.TransmissionPower >= 256 {
		return errors.New(""TransmissionPower out of valid range"")
	}
	return nil
}

func validateChecksum(c *Checksum) error {
	if c.CRCValue == 0 {
		return errors.New(""CRCValue cannot be zero"")
	}
	return nil
}

func main() {
	p, c, err := NewPacketAndChecksum()
	if err != nil {
		log.Fatalf(""Failed to create Packet and Checksum: %v"", err)
	}
	log.Printf(""Created Packet: %+v\n"", p)
	log.Printf(""Created Checksum: %+v\n"", c)
}
