0,"Design a function that takes user input for an array of integers, validates each input, sums the elements, calculates the average, and returns both the total and average. Additionally, handle errors for non-integer inputs and provide options for the user to add more elements or exit the program. The function should also include a feature to save the array to a file and load it later for quick access. Furthermore, incorporate an option for users to choose between calculating the sum and average using either iterative or recursive methods. Finally, implement error handling for file I/O operations and provide informative messages when errors occur during file operations or invalid user inputs are encountered.",680,,"['```python
import json

def validate_input(input_str):
    try:
        return int(input_str)
    except ValueError:
        print(""Invalid input! Please enter an integer."")
        return None

def calculate_sum(numbers, method='iterative'):
    if method == 'iterative':
        total = sum(numbers)
    elif method == 'recursive':
        def recursive_sum(arr):
            return arr[0] + recursive_sum(arr[1:]) if arr else 0
        total = recursive_sum(numbers)
    else:
        raise ValueError(""Invalid method. Please choose 'iterative' or 'recursive'."")
    return total

def calculate_average(total, length):
    if length == 0:
        return 0
    return total / length

def save_array_to_file(array, filename='data.json'):
    try:
        with open(filename, 'w') as file:
            json.dump(array, file)
        print(f""Array saved to {filename}"")
    except IOError as e:
        print(f""Error saving array: {e}"")

def load_array_from_file(filename='data.json'):
    try:
        with open(filename, 'r') as file:
            array = json.load(file)
        return array
    except FileNotFoundError:
        print(""File not found. Starting with an empty array."")
        return []
    except IOError as e:
        print(f""Error loading array: {e}"")
        return []

def main():
    numbers = []
    while True:
        user_input = input(""Enter an integer (or 'exit' to finish): "")
        if user_input.lower() == 'exit':
            break
        num = validate_input(user_input)
        if num is not None:
            numbers.append(num)

    save_array_to_file(numbers)

    total = calculate_sum(numbers, method='iterative')
    average = calculate_average(total, len(numbers))
    print(f""Total: {total}"")
    print(f""Average: {average}"")

if __name__ == ""__main__"":
    main()
