import random

def randomized_pdu(size):
    return {
        'RX_UE_INFORMATION_TAG': ''.join(random.choices('abcdefghijklmnopqrstuvwxyz', k=random.randint(10, 30))),
        'RNTI': ''.join(random.choices('0123456789abcdef', k=4)),
        'CRC_INDICATION_REL8_TAG_CRCFLAG': bool(random.getrandbits(1))
    }

def read_chunks(file):
    chunk_size = 4096
    chunks = []

    while True:
        chunk = file.read(chunk_size)
        if not chunk:
            break

        chunks.append(chunk)

    return b''.join(chunks)

def compute_sha256(data):
    import hashlib

    sha256_hasher = hashlib.sha256()

    for chunk in data:
        sha256_hasher.update(chunk)

    return sha256_hasher.hexdigest()

def generateAndValidate(size, filePath, expectedHash, sizeLimit):
    # Generate array of NFAPI_CRC_INDICATION_PDU_T structures
    pdu_array = [randomized_pdu(size) for _ in range(size)]

    # Append '/' to RX_UE_INFORMATION_TAG if length does not exceed size limit
    for pdu in pdu_array:
        if len(pdu['RX_UE_INFORMATION_TAG']) + 1 <= sizeLimit:
            pdu['RX_UE_INFORMATION_TAG'] += '/'

    # Validate file existence and compute SHA-256 hash
    try:
        with open(filePath, 'r') as file:
            chunks = read_chunks(file)
            computed_hash = compute_sha256(chunks)

        return computed_hash == expectedHash

    except FileNotFoundError:
        raise Exception(""File not found"")

    except Exception as e:
        raise Exception(""Error reading file:"", str(e))
