1,"Create a software application that establishes a connection to a distant server using the server's hostname or IP, verifies user credentials, and proceeds to fetch a designated file from the server. The utility should present the total size of the downloaded file in bytes, and convey any error notifications that occur during the download process. Include an option for saving the downloaded file with a personalized name. Ensure the program adeptly manages possible network issues, offering clear updates to the user regarding successful or unsuccessful download endeavors.",121,,"['```python
import socket
import os

def connect_to_server(hostname, port):
    try:
        client_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        client_socket.connect((hostname, port))
        print(""Connection established successfully."")
        return client_socket
    except Exception as e:
        print(f""Error connecting to server: {e}"")
        return None

def verify_credentials(client_socket, username, password):
    credentials = f""{username}:{password}""
    client_socket.send(credentials.encode())
    response = client_socket.recv(1024).decode()
    if response == ""AUTH_SUCCESS"":
        print(""Credentials verified successfully."")
        return True
    else:
        print(""Invalid credentials. Please try again."")
        return False

def fetch_file(client_socket, file_path):
    try:
        client_socket.send(file_path.encode())
        file_size = int(client_socket.recv(1024).decode())
        print(f""File size: {file_size} bytes"")
        with open('downloaded_file', 'wb') as f:
            received_bytes = 0
            while received_bytes < file_size:
                data = client_socket.recv(1024)
                if not data:
                    break
                f.write(data)
                received_bytes += len(data)
                print(f""Received {received_bytes}/{file_size} bytes"")
        print(""File downloaded successfully."")
    except Exception as e:
        print(f""Error fetching file: {e}"")

def save_file():
    new_name = input(""Enter a new name for the file (leave blank to use default): "")
    if new_name:
        os.rename('downloaded_file', new_name)
        print(f""File saved as {new_name}"")
    else:
        print(""File saved with default name."")

def main():
    hostname = input(""Enter server's hostname or IP: "")
    port = int(input(""Enter server's port: ""))
    username = input(""Enter your username: "")
    password = input(""Enter your password: "")

    client_socket = connect_to_server(hostname, port)
    if client_socket:
        if verify_credentials(client_socket, username, password):
            file_path = input(""Enter the path of the file to download: "")
            fetch_file(client_socket, file_path)
            save_file()

if __name__ == ""__main__"":
    main()
