1,"Create a class named 'FileManager' with a constructor that accepts a file path as an argument. The FileManager class should have a method called 'writeToFile' that takes two parameters: the content to be written and the timestamp. The writeToFile method should write the content to the file at the given path along with the timestamp in the format: ""Timestamp: [timestamp], Content: [content]"". Additionally, implement a private method 'validateFilePath' that checks if the provided file path is valid, ensuring it ends with either '.txt', '.docx', or '.pdf'. If the file path is not valid, throw an exception with an appropriate error message. Finally, include a check function to test if FileManager class functions correctly by creating an instance of FileManager, calling its methods with valid and invalid file paths, and verifying the output.",306,,"['```python
import os
from datetime import datetime

class FileManager:
    def __init__(self, file_path):
        self.validateFilePath(file_path)
        self.file_path = file_path

    def writeToFile(self, content, timestamp=None):
        if timestamp is None:
            timestamp = datetime.now().strftime(""%Y-%m-%d %H:%M:%S"")
        with open(self.file_path, 'a') as file:
            file.write(f""Timestamp: {timestamp}, Content: {content}\n"")

    def validateFilePath(self, file_path):
        valid_extensions = ['.txt', '.docx', '.pdf']
        if not any(file_path.endswith(ext) for ext in valid_extensions):
            raise ValueError(""Invalid file path. Only .txt, .docx, and .pdf files are allowed."")

def check_file_manager():
    try:
        fm_valid = FileManager('example.txt')
        fm_valid.writeToFile('Hello, world!')
        print(""File written successfully with valid file path."")

        fm_invalid = FileManager('example.doc')
        fm_invalid.writeToFile('Invalid extension file.')
    except ValueError as e:
        print(e)

check_file_manager()
