0,"Design and implement a function that takes a list of integers as input and returns the sum of all prime numbers within the list. The function should also handle potential errors, such as non-integer values in the list, by skipping them and continuing with the processing. Additionally, include a feature to track the number of prime numbers found in the list. Finally, optimize the function to improve its performance when dealing with large lists containing millions of integers.",680,,"['```python
def sum_of_primes(numbers):
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    total_sum = 0
    prime_count = 0
    for num in numbers:
        if isinstance(num, int):
            if is_prime(num):
                total_sum += num
                prime_count += 1
    return total_sum, prime_count

# Example usage
numbers = [2, 3, 'a', 4, 5, 'b', 7, 8, 9, 10]
prime_sum, count = sum_of_primes(numbers)
print(f""Sum of primes: {prime_sum}, Number of primes found: {count}"")
