from typing import List, Tuple, Union
import math

class PrimeError(Exception):
    pass

def prime_sum_and_count(input_list: List[int], include_indices: bool = False,
                        optimize_large_lists: bool = True) -> Union[Tuple[int, int],
                                                              Tuple[int, int, List[Tuple[int, int]]]]:
    if not input_list:
        raise ValueError(""Input list cannot be empty"")

    primes = []
    for num in input_list:
        if isinstance(num, int):
            if is_prime(num):
                primes.append(num)
        else:
            raise TypeError(""Non-integer values found in the list. Skipping non-integers."")

    sum_of_primes = sum(primes)
    count_of_primes = len(primes)

    if include_indices and optimize_large_lists:
        prime_indices = [(num, index) for index, num in enumerate(input_list) if is_prime(num)]
        return (sum_of_primes, count_of_primes, prime_indices)
    elif include_indices:
        prime_indices = [(num, input_list.index(num)) for num in primes]
        return (sum_of_primes, count_of_primes, prime_indices)
    else:
        return (sum_of_primes, count_of_primes)

def is_prime(n: int) -> bool:
    if n <= 1:
        return False
    elif n <= 3:
        return True
    elif n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

# Example usage:
try:
    result = prime_sum_and_count([2, 3, 4, 'a', 5], include_indices=True)
    print(result)
except PrimeError as e:
    print(e)
