import argparse
import os

def process_file(input_file, output_file=None):
    if not os.path.isfile(input_file):
        print(""Error: Input file does not exist."")
        sys.exit(1)

    line_count = sum(1 for _ in open(input_file))

    if output_file:
        with open(output_file, 'w') as out_f:
            out_f.write(str(line_count))
    else:
        print(line_count)

def main():
    parser = argparse.ArgumentParser(description=""Count lines in a file"")

    parser.add_argument(""input"", help=""Input file"", type=str)
    parser.add_argument(""-o"", ""--output"", help=""Output file for line count"", type=str)

    args = parser.parse_args()

    if args.output:
        with open(args.output, 'w') as out_f:
            out_f.write(str(process_file(args.input)))
    else:
        print(process_file(args.input))

if __name__ == ""__main__"":
