import sys
import socket
import subprocess

def print_usage():
    print(""Usage: python script.py hostname [-c <file_path>] [--manpage]"")
    sys.exit(0)

def resolve_dns(hostname):
    try:
        ip = socket.gethostbyname(hostname)
        print(f""IP address for {hostname} is {ip}"")
    except socket.gaierror:
        print(f""Error: Unable to resolve {hostname}"")

def count_lines(file_path):
    try:
        with open(file_path, 'r') as file:
            lines = file.readlines()
            line_count = len(lines)
            print(f""Number of lines in '{file_path}': {line_count}"")
    except FileNotFoundError:
        print(f""Error: File '{file_path}' not found"")

def display_manpage():
    subprocess.run([""man"", ""script.py""])

if __name__ == ""__main__"":
    if len(sys.argv) not in [2, 3, 4]:
        print_usage()

    hostname = sys.argv[1]

    if sys.argv[1] == ""-h"":
        print_usage()

    if sys.argv[1] == ""hostname"":
        if len(sys.argv) != 3:
            print_usage()

        if sys.argv[2] == ""-c"":
            if len(sys.argv) != 5:
                print_usage()
            count_lines(sys.argv[4])

        elif sys.argv[2] == ""--manpage"":
            display_manpage()

        else:
            resolve_dns(hostname)

