def GetDesCipherMode(key_size=56, iv=None):
    if key_size not in [56, 112, 168]:
        raise ValueError(""Invalid DES key size. Must be 56, 112, or 168 bits."")
    if iv is None:
        iv = b'\0' * 8
    if len(iv) != 8:
        raise ValueError(""IV must be 8 bytes long."")
    return DES.MODE_CBC if key_size == 56 else DES.MODE_ECB

def ValidateAndEncryptToken(json_string, key_size=56, iv=None):
    cipher_mode = GetDesCipherMode(key_size, iv)
    cipher = DES.new(b'01234567', cipher_mode, iv)
    try:
        parsed_json = json.loads(json_string)
        # Perform validation logic here
        encrypted_data = cipher.encrypt(pad(json.dumps(parsed_json).encode(), DES.block_size))
        return encrypted_data
    except (json.JSONDecodeError, TypeError):
        raise ValueError(""Invalid JSON string."")
