import random
import string

def generate_password(length):
    if length < 8 or length > 16:
        raise ValueError(""Length must be between 8 and 16 characters."")

    all_characters = string.ascii_letters + string.digits + string.punctuation
    while True:
        password = ''.join(random.choice(all_characters) for _ in range(length))
        if (any(c.isupper() for c in password) and
            any(c.islower() for c in password) and
            any(c.isdigit() for c in password) and
            any(c in string.punctuation for c in password)):
            return password

def validate_password(password):
    if not (8 <= len(password) <= 16):
        return False
    if not any(c.isupper() for c in password):
        return False
    if not any(c.islower() for c in password):
        return False
    if not any(c.isdigit() for c in password):
        return False
    if not any(c in string.punctuation for c in password):
        return False
    return True

def generate_unique_passwords(num_passwords):
    unique_passwords = set()
    while len(unique_passwords) < num_passwords:
        password = generate_password(random.randint(8, 16))
        unique_passwords.add(password)
    return list(unique_passwords)

# Example usage
num_passwords_to_generate = 5
password_list = generate_unique_passwords(num_passwords_to_generate)
for password in password_list:
    print(password)
